// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;
    function setUp() public { c = new DEP_BANK(); }
    function testFuzz_property(address sender, uint256 depositAmt, uint256 collectAmt) public {
        vm.assume(depositAmt > 0);
        vm.assume(collectAmt > 0 && collectAmt <= depositAmt);
        vm.assume(sender != address(0));

        vm.prank(address(this));
        c.SetMinSum(0);
        c.SetLogFile(address(new LogSink()));
        c.Initialized();

        vm.deal(sender, depositAmt);
        vm.prank(sender);
        c.Deposit{value: depositAmt}();

        uint256 balanceBefore = c.balances(sender);

        vm.prank(sender);
        c.Collect(collectAmt);

        uint256 balanceAfter = c.balances(sender);
        assertEq(balanceAfter, balanceBefore - collectAmt, "balance delta must equal collect amount");
    }
}

contract LogSink {
    function AddMessage(address, uint256, string memory) external { }
}
